contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 seed) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(true);

        c.seedMarket{value: 0}(seed); if (__ESBMC_reverted()) return;

        c.getFreeKilo(); if (__ESBMC_reverted()) return;

        uint256 myKilo = c.getMyKilo(); if (__ESBMC_reverted()) return;
        uint256 myDrugs = c.getMyDrugs(); if (__ESBMC_reverted()) return;
        uint256 startingKilos = c.STARTING_KILOS(); if (__ESBMC_reverted()) return;

        assert(myKilo == startingKilos && myDrugs == 0);
    }

    receive() external payable {}
}

