// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seed) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        try c.seedMarket{value: 0}(seed) {} catch { return; }
        try c.getFreeKilo() {} catch { return; }
        uint256 myKilo;
        try c.getMyKilo() returns (uint256 __r) { myKilo = __r; } catch { return; }
        uint256 myDrugs;
        try c.getMyDrugs() returns (uint256 __r) { myDrugs = __r; } catch { return; }
        uint256 startingKilos;
        try c.STARTING_KILOS() returns (uint256 __r) { startingKilos = __r; } catch { return; }
        assertTrue(myKilo == startingKilos && myDrugs == 0);
    }

    function testFuzz_run(uint256 seed) public {
        _run(seed);
    }

    receive() external payable {}
}
